fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0, we can safely iterate from 1 to arr.len() - 1
    for i in 1..arr.len() {
        // If any pair is found where the previous element is greater than the current,
        // then the array is not sorted in nondecreasing order
        if arr[i - 1] > arr[i] {
            return false;
        }
    }
    true
}